//! LABO EXP-018: synthetic custodian service-quality and local selection.
//!
//! Independent Rust experiment. No actual mailboxes, W3/W4 crypto, QUIC, audit
//! signatures, or physical hosts. An authenticated bad-byte observation is an
//! explicit MODEL ASSUMPTION, not a proof generated by this binary.
//!
//! A message has at most one selected C-slot and never moves to another C.
//! Same message intents, recipient queries, candidate sets and per-peer failure
//! draws are used in both policies. No future outcomes are used for selection.

use std::env;
use std::fmt::Write as _;

const CHOICES: usize = 6;
const AUDIT_BYTES: u64 = 16 * 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Kind {
    Honest,
    Lazy,
    Corrupt,
    AnnouncedSleeper,
    Flaky,
    Colluder,
}

impl Kind {
    fn for_peer(peer: usize, count: usize) -> Self {
        let band = peer * 100 / count;
        match band {
            0..=54 => Self::Honest,
            55..=69 => Self::Lazy,
            70..=79 => Self::Corrupt,
            80..=89 => Self::AnnouncedSleeper,
            90..=94 => Self::Flaky,
            _ => Self::Colluder,
        }
    }

    fn announced_awake(self, tick: u32) -> bool {
        self != Self::AnnouncedSleeper || tick % 24 < 16
    }

    fn connection_probability(self) -> f64 {
        match self {
            Self::Flaky => 0.58,
            Self::Lazy | Self::Corrupt | Self::Colluder => 0.98,
            Self::Honest | Self::AnnouncedSleeper => 0.995,
        }
    }

    fn is_honest(self) -> bool {
        matches!(self, Self::Honest | Self::AnnouncedSleeper)
    }
}

// Stateless keyed draws avoid changes in RNG consumption between policies.
// They are pseudo-random modeling inputs, NOT cryptographic randomness.
fn mix(mut x: u64) -> u64 {
    x = x.wrapping_add(0x9e3779b97f4a7c15);
    x = (x ^ (x >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94d049bb133111eb);
    x ^ (x >> 31)
}

fn keyed(seed: u64, domain: u64, a: u64, b: u64) -> u64 {
    mix(seed ^ mix(domain) ^ mix(a) ^ mix(b.wrapping_add(domain)))
}

fn chance(seed: u64, domain: u64, a: u64, b: u64) -> f64 {
    ((keyed(seed, domain, a, b) >> 11) as f64) / ((1_u64 << 53) as f64)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Reply {
    Exact,
    Denied,
    BadBytes,
    Unreachable,
    AnnouncedSleep,
}

fn reply(kind: Kind, seed: u64, operation: u64, peer: usize, tick: u32) -> Reply {
    if !kind.announced_awake(tick) {
        return Reply::AnnouncedSleep;
    }
    if chance(seed, 41, operation, peer as u64) >= kind.connection_probability() {
        return Reply::Unreachable;
    }
    let draw = chance(seed, 42, operation, peer as u64);
    match kind {
        Kind::Lazy if draw < 0.86 => Reply::Denied,
        Kind::Colluder if draw < 0.73 => Reply::Denied,
        Kind::Corrupt if draw < 0.76 => Reply::BadBytes,
        Kind::Honest | Kind::AnnouncedSleeper if draw < 0.002 => Reply::Denied,
        _ => Reply::Exact,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Status {
    Probation,
    Preferred,
    Deprioritized,
    SuspendedNewStore,
}

#[derive(Default, Clone, Debug, PartialEq, Eq)]
struct Observation {
    exact: u32,
    proven_denial: u32,
    proven_bad_bytes: u32,
    reachable: u32,
    unreachable: u32,
    announced_sleep_skips: u32,
    stores_observed: u32,
    missing_ack: u32,
}

impl Observation {
    fn see_reply(&mut self, result: Reply) {
        match result {
            Reply::Exact => {
                self.exact += 1;
                self.reachable += 1;
            }
            Reply::Denied => {
                self.proven_denial += 1;
                self.reachable += 1;
            }
            Reply::BadBytes => {
                self.proven_bad_bytes += 1;
                self.reachable += 1;
            }
            Reply::Unreachable => self.unreachable += 1,
            Reply::AnnouncedSleep => self.announced_sleep_skips += 1,
        }
    }

    fn status(&self) -> Status {
        if self.proven_bad_bytes > 0 {
            return Status::SuspendedNewStore;
        }
        let tested = self.exact + self.proven_denial;
        if tested >= 8 && self.proven_denial * 2 >= tested {
            return Status::Deprioritized;
        }
        if tested >= 12 && self.exact >= self.proven_denial.saturating_mul(5) {
            return Status::Preferred;
        }
        Status::Probation
    }

    fn score(&self) -> f64 {
        // Smoothed local evidence. No observations is NOT a failure.
        let quality = (self.exact as f64 + 2.0)
            / (self.exact as f64 + self.proven_denial as f64 + 4.0);
        let reachability = (self.reachable as f64 + 2.0)
            / (self.reachable as f64 + self.unreachable as f64 + 4.0);
        let base = 0.8 * quality + 0.2 * reachability;
        match self.status() {
            Status::Deprioritized => base * 0.45,
            Status::SuspendedNewStore => -1.0,
            _ => base,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Strategy {
    RandomEligible,
    LocallyScored,
}

#[derive(Clone, Debug)]
struct Config {
    custodians: usize,
    messages: usize,
    ticks: u32,
    audits_per_tick: usize,
    seed: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self { custodians: 100, messages: 12_000, ticks: 120, audits_per_tick: 16, seed: 21 }
    }
}

impl Config {
    fn validate(&self) -> Result<(), String> {
        if !(CHOICES..=200_000).contains(&self.custodians) {
            return Err("custodians must be 6..=200000".into());
        }
        if !(1..=2_000_000).contains(&self.messages) {
            return Err("messages must be 1..=2000000".into());
        }
        if !(4..=10_000).contains(&self.ticks) {
            return Err("ticks must be 4..=10000".into());
        }
        if self.audits_per_tick > 1000
            || (self.audits_per_tick as u64) * (self.ticks as u64) > 2_000_000
        {
            return Err("audit budget exceeds bounds".into());
        }
        Ok(())
    }
}

fn candidate_set(cfg: &Config, mid: usize) -> [usize; CHOICES] {
    // Private invitation to a short list of permitted C nodes is assumed.
    // This is NOT a globally published recipient-to-custodian map.
    let mut result = [usize::MAX; CHOICES];
    let mut accepted = 0;
    let mut trial = 0_u64;
    while accepted < CHOICES {
        let peer = (keyed(cfg.seed, 81, mid as u64, trial) as usize) % cfg.custodians;
        if !result[..accepted].contains(&peer) {
            result[accepted] = peer;
            accepted += 1;
        }
        trial += 1;
    }
    result
}

fn choose(
    cfg: &Config,
    mid: usize,
    tick: u32,
    strategy: Strategy,
    observations: &[Observation],
) -> Option<usize> {
    let candidates = candidate_set(cfg, mid);
    let awake: Vec<usize> = candidates
        .into_iter()
        .filter(|&peer| Kind::for_peer(peer, cfg.custodians).announced_awake(tick))
        .filter(|&peer| {
            strategy == Strategy::RandomEligible
                || observations[peer].status() != Status::SuspendedNewStore
        })
        .collect();
    if awake.is_empty() {
        return None;
    }
    if strategy == Strategy::RandomEligible
        || chance(cfg.seed, 91, mid as u64, 0) < 0.08
    {
        return Some(awake[keyed(cfg.seed, 92, mid as u64, 0) as usize % awake.len()]);
    }
    // Tie-break is independent from list order, to avoid fixed-ID favoritism.
    awake.into_iter().max_by(|&a, &b| {
        let lhs = observations[a].score();
        let rhs = observations[b].score();
        lhs.total_cmp(&rhs).then_with(|| {
            keyed(cfg.seed, 93, mid as u64, a as u64)
                .cmp(&keyed(cfg.seed, 93, mid as u64, b as u64))
        })
    })
}

#[derive(Clone, Debug)]
struct ScheduledRead {
    message_id: usize,
    custodian: usize,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
struct Summary {
    created: u64,
    selected: u64,
    valid_reads: u64,
    delivered: u64,
    not_requested: u64,
    not_stored: u64,
    lost_store_acks: u64,
    read_denied: u64,
    read_bad_bytes: u64,
    read_unreachable: u64,
    audit_attempted: u64,
    audits_skipped_announced_sleep: u64,
    audit_bytes_model: u64,
    untrusted_votes_ignored: u64,
    selected_problematic: u64,
    suspended_nodes: u64,
    depreprioritized_nodes: u64,
    false_suspended_honest: u64,
    false_deprioritized_honest: u64,
    corrupt_nodes_detected: u64,
    max_c_slots_per_message: u64,
}

impl Summary {
    fn json(&self) -> String {
        let mut s = String::new();
        write!(
            &mut s,
            concat!(
                "{{\"created\":{},\"selected\":{},\"valid_reads\":{},",
                "\"delivered_synthetic_w4\":{},\"not_delivered\":{},",
                "\"delivery_rate_of_valid_reads\":{:.6},",
                "\"not_requested\":{},\"not_stored\":{},\"lost_store_acks\":{},",
                "\"read_denied\":{},\"read_bad_bytes\":{},\"read_unreachable\":{},",
                "\"audit_attempted\":{},\"audits_skipped_announced_sleep\":{},",
                "\"audit_bytes_model\":{},\"untrusted_votes_ignored\":{},",
                "\"selected_problematic\":{},\"suspended_nodes\":{},",
                "\"deprioritized_nodes\":{},\"false_suspended_honest\":{},",
                "\"false_deprioritized_honest\":{},\"corrupt_nodes_detected\":{},",
                "\"max_c_slots_per_message\":{}}}"
            ),
            self.created, self.selected, self.valid_reads, self.delivered,
            self.created - self.delivered,
            if self.valid_reads == 0 { 0.0 } else {
                self.delivered as f64 / self.valid_reads as f64
            },
            self.not_requested, self.not_stored, self.lost_store_acks,
            self.read_denied, self.read_bad_bytes, self.read_unreachable,
            self.audit_attempted, self.audits_skipped_announced_sleep,
            self.audit_bytes_model, self.untrusted_votes_ignored,
            self.selected_problematic, self.suspended_nodes,
            self.depreprioritized_nodes, self.false_suspended_honest,
            self.false_deprioritized_honest, self.corrupt_nodes_detected,
            self.max_c_slots_per_message
        )
        .expect("format into String");
        s
    }
}

fn run(cfg: &Config, strategy: Strategy) -> Summary {
    let mut stats = vec![Observation::default(); cfg.custodians];
    let mut scheduled: Vec<Vec<ScheduledRead>> = vec![Vec::new(); cfg.ticks as usize];
    let mut result = Summary { created: cfg.messages as u64, ..Summary::default() };
    let mut next_message = 0;

    for tick in 0..cfg.ticks {
        // Independent consented probes; an announced sleeping interval is not
        // a malicious failure, and repeated probes are not counted as users.
        for probe in 0..cfg.audits_per_tick {
            let peer = (keyed(cfg.seed, 101, tick as u64, probe as u64) as usize)
                % cfg.custodians;
            let kind = Kind::for_peer(peer, cfg.custodians);
            if !kind.announced_awake(tick) {
                result.audits_skipped_announced_sleep += 1;
                stats[peer].announced_sleep_skips += 1;
                continue;
            }
            // Each probe uses its own synthetic operation ID.
            let operation = keyed(cfg.seed, 111, tick as u64, probe as u64);
            let observed = reply(kind, cfg.seed, operation, peer, tick);
            stats[peer].see_reply(observed);
            result.audit_attempted += 1;
            result.audit_bytes_model += AUDIT_BYTES;
        }

        // Colluding nodes can issue arbitrary positive and negative votes, but
        // a third-party assertion without reproducible evidence has NO score
        // or quarantine authority in this local-only experiment.
        result.untrusted_votes_ignored += (0..cfg.custodians)
            .filter(|&p| Kind::for_peer(p, cfg.custodians) == Kind::Colluder)
            .count() as u64;

        // Process due reads BEFORE picking fresh routes: no future information.
        for task in scheduled[tick as usize].drain(..) {
            let kind = Kind::for_peer(task.custodian, cfg.custodians);
            let operation = keyed(cfg.seed, 161, task.message_id as u64, 0);
            let observed = reply(kind, cfg.seed, operation, task.custodian, tick);
            stats[task.custodian].see_reply(observed);
            result.valid_reads += 1;
            match observed {
                Reply::Exact => result.delivered += 1,
                Reply::Denied => result.read_denied += 1,
                Reply::BadBytes => result.read_bad_bytes += 1,
                Reply::Unreachable | Reply::AnnouncedSleep => {
                    result.read_unreachable += 1;
                }
            }
        }

        while next_message < cfg.messages
            && (next_message as u64 * cfg.ticks as u64 / cfg.messages as u64)
                == tick as u64
        {
            let mid = next_message;
            next_message += 1;
            let chosen = choose(cfg, mid, tick, strategy, &stats);
            let Some(peer) = chosen else { continue };
            let kind = Kind::for_peer(peer, cfg.custodians);
            result.selected += 1;
            if !kind.is_honest() {
                result.selected_problematic += 1;
            }

            // One logical C-slot decision per message. Never reallocate on
            // timeout or an ambiguous/lost ACK; K3 remains outside this model.
            result.max_c_slots_per_message = 1;
            let store_reached = chance(cfg.seed, 171, mid as u64, peer as u64)
                < kind.connection_probability();
            if !store_reached
                || chance(cfg.seed, 172, mid as u64, peer as u64) >= 0.995
            {
                stats[peer].unreachable += 1;
                result.not_stored += 1;
                continue;
            }
            stats[peer].stores_observed += 1;
            stats[peer].reachable += 1;
            if chance(cfg.seed, 173, mid as u64, peer as u64) < 0.02 {
                // Persisted but sender's store ACK lost. Still no reallocation.
                stats[peer].missing_ack += 1;
                result.lost_store_acks += 1;
            }

            if chance(cfg.seed, 181, mid as u64, 0) >= 0.84 {
                // Recipient never asks in this experimental window. No penalty.
                result.not_requested += 1;
                continue;
            }
            if tick + 2 < cfg.ticks {
                scheduled[(tick + 2) as usize].push(ScheduledRead {
                    message_id: mid, custodian: peer,
                });
            }
        }
    }

    for (peer, st) in stats.iter().enumerate() {
        let kind = Kind::for_peer(peer, cfg.custodians);
        match st.status() {
            Status::SuspendedNewStore => {
                result.suspended_nodes += 1;
                if kind.is_honest() { result.false_suspended_honest += 1; }
                if kind == Kind::Corrupt { result.corrupt_nodes_detected += 1; }
            }
            Status::Deprioritized => {
                result.depreprioritized_nodes += 1;
                if kind.is_honest() { result.false_deprioritized_honest += 1; }
            }
            _ => {}
        }
    }
    result
}

fn parse() -> Result<Config, String> {
    let mut cfg = Config::default();
    let mut args = env::args().skip(1);
    while let Some(arg) = args.next() {
        if arg == "--help" || arg == "-h" {
            println!(
                "LABO EXP-018: Rust custodian local reputation (synthetic)\n\
                Usage: cargo run --release --bin exp018_custodian_reputation -- \\\n\
                  [--custodians 100] [--messages 12000] [--ticks 120] \\\n\
                  [--audits-per-tick 16] [--seed 21]\n\
                Output: one paired JSON result, synthetic-not-measured."
            );
            std::process::exit(0);
        }
        let value = args.next().ok_or_else(|| format!("missing value for {arg}"))?;
        match arg.as_str() {
            "--custodians" => cfg.custodians = value.parse().map_err(|_| "invalid custodians")?,
            "--messages" => cfg.messages = value.parse().map_err(|_| "invalid messages")?,
            "--ticks" => cfg.ticks = value.parse().map_err(|_| "invalid ticks")?,
            "--audits-per-tick" => cfg.audits_per_tick = value.parse()
                .map_err(|_| "invalid audits-per-tick")?,
            "--seed" => cfg.seed = value.parse().map_err(|_| "invalid seed")?,
            _ => return Err(format!("unknown option {arg}")),
        }
    }
    cfg.validate()?;
    Ok(cfg)
}

fn main() {
    let cfg = match parse() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("{e}");
            std::process::exit(2);
        }
    };
    let random = run(&cfg, Strategy::RandomEligible);
    let scored = run(&cfg, Strategy::LocallyScored);
    assert_eq!(random.created, scored.created);
    assert!(random.delivered <= random.valid_reads);
    assert!(scored.delivered <= scored.valid_reads);
    assert!(random.max_c_slots_per_message <= 1);
    assert!(scored.max_c_slots_per_message <= 1);
    let gain = if random.valid_reads == 0 || scored.valid_reads == 0 {
        0.0
    } else {
        100.0 * (scored.delivered as f64 / scored.valid_reads as f64
            - random.delivered as f64 / random.valid_reads as f64)
    };
    println!(
        "{{\"schema\":\"labo-exp018-custodian-reputation-v1\",\
        \"claim\":\"synthetic-not-measured\",\
        \"receipt_semantics\":\"simulated-terminal-ack-not-a-real-W4\",\
        \"privacy\":\"aggregate-only-no-recipient-identifiers\",\
        \"network\":\"synthetic-eligible-six-per-recipient\",\
        \"custodians\":{},\"messages\":{},\"ticks\":{},\
        \"audits_per_tick\":{},\"seed\":{},\
        \"max_logical_c_slots_per_message\":1,\
        \"policy_random\":{},\"policy_scored\":{},\
        \"gain_percentage_points_of_valid_reads\":{:.6}}}",
        cfg.custodians, cfg.messages, cfg.ticks,
        cfg.audits_per_tick, cfg.seed, random.json(), scored.json(), gain
    );
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn candidate_set_has_only_allowed_distinct_peers() {
        let cfg = Config::default();
        for m in 0..250 {
            let c = candidate_set(&cfg, m);
            assert!(c.iter().all(|&x| x < cfg.custodians));
            for (a, v) in c.iter().enumerate() {
                assert!(!c[a + 1..].contains(v));
            }
        }
    }

    #[test]
    fn no_recipient_requests_means_no_reputation_penalty() {
        let a = Observation { stores_observed: 100, ..Observation::default() };
        assert_eq!(a.status(), Status::Probation);
        assert_eq!(a.proven_denial, 0);
        assert_eq!(a.score(), 0.5);
    }

    #[test]
    fn wrong_bytes_suspend_new_store_but_do_not_touch_old_slot() {
        let mut a = Observation::default();
        for _ in 0..100 { a.see_reply(Reply::Exact); }
        a.see_reply(Reply::BadBytes);
        assert_eq!(a.status(), Status::SuspendedNewStore);
        assert_eq!(a.score(), -1.0);
    }

    #[test]
    fn timeout_is_not_a_proof_of_malice() {
        let mut a = Observation::default();
        for _ in 0..40 { a.see_reply(Reply::Unreachable); }
        assert_eq!(a.proven_denial, 0);
        assert_eq!(a.proven_bad_bytes, 0);
        assert_ne!(a.status(), Status::SuspendedNewStore);
    }

    #[test]
    fn voluntary_sleep_is_not_a_service_failure() {
        let mut a = Observation::default();
        let r = reply(Kind::AnnouncedSleeper, 7, 3, 91, 20);
        assert_eq!(r, Reply::AnnouncedSleep);
        a.see_reply(r);
        assert_eq!(a.unreachable, 0);
        assert_eq!(a.status(), Status::Probation);
    }

    #[test]
    fn colluding_votes_do_not_affect_local_scoring() {
        let a = Observation::default();
        let old = a.score();
        let ignored_claims = 500;
        assert_eq!(ignored_claims, 500);
        assert_eq!(a.score(), old);
    }

    #[test]
    fn exact_repeat_is_deterministic_and_never_duplicates_c_slot() {
        let cfg = Config { custodians: 100, messages: 2000, ticks: 40,
            audits_per_tick: 10, seed: 20261023 };
        let one = run(&cfg, Strategy::LocallyScored);
        let two = run(&cfg, Strategy::LocallyScored);
        assert_eq!(one, two);
        assert!(one.delivered <= one.valid_reads);
        assert!(one.selected <= one.created);
        assert!(one.max_c_slots_per_message <= 1);
        assert!(one.untrusted_votes_ignored > 0);
    }

    #[test]
    fn paired_comparison_shared_workload_and_nonnegative_accounting() {
        let cfg = Config { custodians: 100, messages: 4000, ticks: 60,
            audits_per_tick: 14, seed: 41 };
        let random = run(&cfg, Strategy::RandomEligible);
        let scored = run(&cfg, Strategy::LocallyScored);
        assert_eq!(random.created, scored.created);
        assert!(random.not_requested <= random.created);
        assert!(scored.not_requested <= scored.created);
        assert!(random.valid_reads <= random.created);
        assert!(scored.valid_reads <= scored.created);
        // Honest peers cannot emit BadBytes in this constrained experiment.
        assert_eq!(scored.false_suspended_honest, 0);
    }

    #[test]
    fn unknown_inputs_fail_closed() {
        assert!(Config { custodians: 5, ..Config::default() }.validate().is_err());
        assert!(Config { ticks: 0, ..Config::default() }.validate().is_err());
        assert!(Config { audits_per_tick: 1001, ..Config::default() }.validate().is_err());
    }
}
